#include <hip/hip_runtime.h>

#define BM 64
#define BN 64
#define BK 16
#define TM 4
#define TN 4

__global__ void sgemm_tiled_vec(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int M, int N, int K) {
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int tid = ty * blockDim.x + tx;

    __shared__ float As[BM][BK];
    __shared__ float Bs[BK][BN];

    float c_reg[TM][TN] = {0.0f};

    const float* A_ptr = A + by * BM * K;
    const float* B_ptr = B + bx * BN;

    // Loading indices for this thread
    // Total threads = 256. 4 floats per thread.
    int a_load_idx = tid * 4;
    int a_load_row = a_load_idx / BK;
    int a_load_col = a_load_idx % BK;

    int b_load_idx = tid * 4;
    int b_load_row = b_load_idx / BN;
    int b_load_col = b_load_idx % BN;

    for (int k = 0; k < K; k += BK) {
        // Vectorized load from Global A
        float4 a_vec = *reinterpret_cast<const float4*>(&A_ptr[a_load_row * K + k + a_load_col]);
        *reinterpret_cast<float4*>(&As[a_load_row][a_load_col]) = a_vec;

        // Vectorized load from Global B
        float4 b_vec = *reinterpret_cast<const float4*>(&B_ptr[(k + b_load_row) * N + b_load_col]);
        *reinterpret_cast<float4*>(&Bs[b_load_row][b_load_col]) = b_vec;

        __syncthreads();

        // Compute
        #pragma unroll
        for (int i = 0; i < BK; ++i) {
            float4 b_val_vec = *reinterpret_cast<float4*>(&Bs[i][tx * TN]);
            float b_vals[4] = {b_val_vec.x, b_val_vec.y, b_val_vec.z, b_val_vec.w};

            #pragma unroll
            for (int r = 0; r < TM; ++r) {
                float a_val = As[ty * TM + r][i];
                for (int c = 0; c < TN; ++c) {
                    c_reg[r][c] += a_val * b_vals[c];
                }
            }
        }

        __syncthreads();
    }

    // Store C
    int c_global_row = by * BM + ty * TM;
    int c_global_col = bx * BN + tx * TN;

    #pragma unroll
    for (int r = 0; r < TM; ++r) {
         float4 c_vec;
         c_vec.x = c_reg[r][0];
         c_vec.y = c_reg[r][1];
         c_vec.z = c_reg[r][2];
         c_vec.w = c_reg[r][3];
         *reinterpret_cast<float4*>(&C[(c_global_row + r) * N + c_global_col]) = c_vec;
    }
}

